import{_ as a,o as n,c as s,ae as e}from"./chunks/framework.RRduUuAx.js";const g=JSON.parse('{"title":"独立开发者的技术选型：从产品定位到长期演进","description":"","frontmatter":{},"headers":[],"relativePath":"posts/indie-developer-tech-selection.md","filePath":"posts/indie-developer-tech-selection.md"}'),p={name:"posts/indie-developer-tech-selection.md"};function o(d,t,r,i,l,c){return n(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="独立开发者的技术选型-从产品定位到长期演进" tabindex="-1">独立开发者的技术选型：从产品定位到长期演进 <a class="header-anchor" href="#独立开发者的技术选型-从产品定位到长期演进" aria-label="Permalink to &quot;独立开发者的技术选型：从产品定位到长期演进&quot;">​</a></h1><p>目前我在规划和开发两个长期产品。</p><p>第一个是面向商业化的企业 SaaS 产品。</p><p>第二个是开源项目 <strong>Evolary</strong>，一个 AI 驱动的个人与家庭长期成长记忆平台。我自己也是它的目标用户，产品重点探索长期数据记录与 AI Native 能力。</p><p>两个产品定位不同，因此我没有强行统一技术栈，而是分别选择了两条路线。</p><h2 id="商业-saas-以稳定、成熟生态和长期维护为主" tabindex="-1">商业 SaaS：以稳定、成熟生态和长期维护为主 <a class="header-anchor" href="#商业-saas-以稳定、成熟生态和长期维护为主" aria-label="Permalink to &quot;商业 SaaS：以稳定、成熟生态和长期维护为主&quot;">​</a></h2><p>技术栈：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.NET 10</span></span>
<span class="line"><span>PostgreSQL</span></span>
<span class="line"><span>Redis</span></span>
<span class="line"><span>RabbitMQ</span></span>
<span class="line"><span>Vue 3</span></span>
<span class="line"><span>Flutter</span></span>
<span class="line"><span>Docker / Linux</span></span></code></pre></div><p>对于商业产品，我更关心的是：</p><p><strong>稳定性、长期维护、生态成熟度、团队扩展能力，以及技术生态的国际通用性。</strong></p><p>因此，这套技术栈整体偏向成熟、稳定的国际企业软件技术生态。</p><h2 id="evolary-一条更偏-ai-native-的探索路线" tabindex="-1">Evolary：一条更偏 AI Native 的探索路线 <a class="header-anchor" href="#evolary-一条更偏-ai-native-的探索路线" aria-label="Permalink to &quot;Evolary：一条更偏 AI Native 的探索路线&quot;">​</a></h2><p>技术栈：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Python</span></span>
<span class="line"><span>FastAPI</span></span>
<span class="line"><span>MySQL</span></span>
<span class="line"><span>Qdrant</span></span>
<span class="line"><span>uni-app</span></span></code></pre></div><p>Evolary 和商业 SaaS 承担的是不同任务。</p><p>它是一个长期维护的开源产品，也是我系统实践 <strong>AI Native、Agent、RAG、向量检索</strong>，以及国内客户端技术生态的项目。</p><table tabindex="0"><thead><tr><th></th><th>商业 SaaS</th><th>Evolary</th></tr></thead><tbody><tr><td>性质</td><td>商业闭源</td><td>开源</td></tr><tr><td>目标</td><td>稳定交付</td><td>技术探索</td></tr><tr><td>技术方向</td><td>企业软件 / 国际化</td><td>AI Native / 国内生态</td></tr><tr><td>后端</td><td>.NET 10</td><td>Python + FastAPI</td></tr><tr><td>数据库</td><td>PostgreSQL</td><td>MySQL + Qdrant</td></tr><tr><td>App</td><td>Flutter</td><td>uni-app</td></tr><tr><td>核心原则</td><td><strong>求稳</strong></td><td><strong>探索</strong></td></tr></tbody></table><p>商业 SaaS 偏向成熟的国际企业软件技术生态；Evolary 则主动进入 Python AI 生态，同时增加对国内客户端技术体系的实践。</p><h2 id="ai-agent-不会只属于-python" tabindex="-1">AI Agent 不会只属于 Python <a class="header-anchor" href="#ai-agent-不会只属于-python" aria-label="Permalink to &quot;AI Agent 不会只属于 Python&quot;">​</a></h2><p>我认为 AI Agent 最终不会是 Python 独占的技术能力。</p><p>Python 今天的优势，更多来自 AI 生态的成熟度。随着 AI 能力逐渐融入主流软件开发，<strong>.NET、Java、TypeScript、Go</strong> 等主流技术生态都会逐渐形成自己的 Agent 开发体系。</p><p>因此，我更关注 Agent 背后的通用能力，而不是押注某一种语言。</p><p>对我而言，这两个产品承担着不同角色：</p><blockquote><p><strong>商业产品负责稳定落地，开源产品负责探索未来。</strong></p></blockquote><p><strong>一个求稳，一个探索。</strong></p>`,25)])])}const v=a(p,[["render",o]]);export{g as __pageData,v as default};
